// Per-instance TLS material for lightning instances. LND's and clnrest's
// autogenerated certs are self-signed with CA:TRUE in the leaf position —
// Go and OpenSSL tolerate that shape, but strict stacks (rustls/webpki)
// reject it. We provision a small CA plus a CA:FALSE leaf instead, so every
// client pins the CA and standard chain validation applies.

use std::net::IpAddr;
use std::str::FromStr as _;

use rcgen::{
    BasicConstraints, CertificateParams, DnType, ExtendedKeyUsagePurpose, Ia5String, IsCa, KeyPair,
    KeyUsagePurpose, SanType,
};

/// PEM material for one lightning instance. The server leaf is what the
/// node serves; the CA is what clients pin. The client pair and CA key
/// exist so clnrest's six-file generation check is satisfied by
/// pre-seeded material — it does not enforce client certificates.
pub struct InstanceTls {
    /// CA certificate. The bundle carries it; clients pin it as a root.
    pub ca_pem: String,
    /// Leaf + CA chain: the file the node serves.
    pub chain_pem: String,
    /// Leaf private key (PKCS8): the file the node serves with.
    pub key_pem: String,
    /// Client leaf signed by the same CA (clnrest expects it on disk).
    pub client_pem: String,
    /// Client leaf private key (PKCS8).
    pub client_key_pem: String,
    /// CA private key (PKCS8), so clnrest's ca-key.pem check passes.
    pub ca_key_pem: String,
}

/// Names one instance's leaf must answer to: in-cluster DNS, loopback,
/// and the deployment's public host — the host every bundle URL uses.
fn subject_alt_names(
    service: &str,
    instance: &str,
    namespace: &str,
    public_host: &str,
) -> Result<Vec<SanType>, rcgen::Error> {
    let dns = |name: &str| -> Result<SanType, rcgen::Error> {
        Ok(SanType::DnsName(Ia5String::try_from(name.to_string())?))
    };
    let mut sans = vec![
        dns("localhost")?,
        SanType::IpAddress(IpAddr::from([127, 0, 0, 1])),
        dns(&format!("{service}-{instance}"))?,
        dns(&format!("{service}-{instance}.{namespace}.svc"))?,
        dns(&format!(
            "{service}-{instance}.{namespace}.svc.cluster.local"
        ))?,
        dns(&format!(
            "{service}-{instance}-0.{service}-{instance}.{namespace}.svc.cluster.local"
        ))?,
    ];
    if let Ok(ip) = IpAddr::from_str(public_host) {
        sans.push(SanType::IpAddress(ip));
    } else if !public_host.is_empty() {
        sans.push(dns(public_host)?);
    }
    Ok(sans)
}

fn ca_params() -> Result<CertificateParams, rcgen::Error> {
    let mut params = CertificateParams::new(vec![])?;
    params
        .distinguished_name
        .push(DnType::CommonName, "signet lnd ca");
    // Constrained(0): the instance CA signs leaves, nothing else.
    params.is_ca = IsCa::Ca(BasicConstraints::Constrained(0));
    params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];
    Ok(params)
}

fn leaf_params(
    service: &str,
    instance: &str,
    sans: Vec<SanType>,
) -> Result<CertificateParams, rcgen::Error> {
    let mut params = CertificateParams::new(vec![])?;
    params
        .distinguished_name
        .push(DnType::CommonName, format!("{service}-{instance}"));
    params.subject_alt_names = sans;
    params.is_ca = IsCa::ExplicitNoCa;
    params.key_usages = vec![
        KeyUsagePurpose::DigitalSignature,
        KeyUsagePurpose::KeyEncipherment,
    ];
    params.extended_key_usages = vec![
        ExtendedKeyUsagePurpose::ServerAuth,
        ExtendedKeyUsagePurpose::ClientAuth,
    ];
    Ok(params)
}

fn client_params(service: &str) -> Result<CertificateParams, rcgen::Error> {
    let mut params = CertificateParams::new(vec![])?;
    params
        .distinguished_name
        .push(DnType::CommonName, format!("{service} rest client"));
    params.is_ca = IsCa::ExplicitNoCa;
    params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
    params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ClientAuth];
    Ok(params)
}

/// rcgen's default validity window spans 1975-4096; sandbox
/// environments are disposable, so there is no rotation machinery.
pub fn generate_instance_tls(
    service: &str,
    instance: &str,
    namespace: &str,
    public_host: &str,
) -> Result<InstanceTls, rcgen::Error> {
    let sans = subject_alt_names(service, instance, namespace, public_host)?;
    let ca_key = KeyPair::generate()?;
    let ca = ca_params()?.self_signed(&ca_key)?;
    let leaf_key = KeyPair::generate()?;
    let leaf = leaf_params(service, instance, sans)?.signed_by(&leaf_key, &ca, &ca_key)?;
    let client_key = KeyPair::generate()?;
    let client = client_params(service)?.signed_by(&client_key, &ca, &ca_key)?;
    Ok(InstanceTls {
        ca_pem: ca.pem(),
        chain_pem: format!("{}{}", leaf.pem(), ca.pem()),
        key_pem: leaf_key.serialize_pem(),
        client_pem: client.pem(),
        client_key_pem: client_key.serialize_pem(),
        ca_key_pem: ca_key.serialize_pem(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dns(name: &str) -> SanType {
        SanType::DnsName(Ia5String::try_from(name.to_string()).unwrap())
    }

    #[test]
    fn the_ca_is_a_constrained_ca() {
        let params = ca_params().unwrap();
        assert!(matches!(
            params.is_ca,
            IsCa::Ca(BasicConstraints::Constrained(0))
        ));
    }

    #[test]
    fn the_leaf_is_not_a_ca_and_serves_both_roles() {
        let params = leaf_params("lnd", "ln-alice", vec![]).unwrap();
        assert!(matches!(params.is_ca, IsCa::ExplicitNoCa));
        assert!(
            params
                .extended_key_usages
                .contains(&ExtendedKeyUsagePurpose::ServerAuth)
        );
        assert!(
            params
                .extended_key_usages
                .contains(&ExtendedKeyUsagePurpose::ClientAuth)
        );
    }

    #[test]
    fn the_public_host_lands_in_the_sans_as_ip_or_dns() {
        let sans = subject_alt_names("lnd", "ln-alice", "env-x", "192.168.100.2").unwrap();
        assert!(sans.contains(&SanType::IpAddress(IpAddr::from([192, 168, 100, 2]))));

        let sans = subject_alt_names("lnd", "ln-alice", "env-x", "ln.example.com").unwrap();
        assert!(sans.contains(&dns("ln.example.com")));
    }

    #[test]
    fn instance_and_cluster_names_are_always_covered() {
        let sans = subject_alt_names("cln", "ln-carol", "env-x", "").unwrap();
        let names: Vec<&str> = sans
            .iter()
            .filter_map(|s| match s {
                SanType::DnsName(name) => Some(name.as_str()),
                _ => None,
            })
            .collect();
        for name in [
            "localhost",
            "cln-ln-carol",
            "cln-ln-carol.env-x.svc",
            "cln-ln-carol.env-x.svc.cluster.local",
            "cln-ln-carol-0.cln-ln-carol.env-x.svc.cluster.local",
        ] {
            assert!(names.contains(&name), "missing {name}");
        }
    }

    #[test]
    fn generation_yields_pinable_material() {
        let tls = generate_instance_tls("lnd", "ln-alice", "env-x", "192.168.100.2").unwrap();
        assert!(tls.ca_pem.starts_with("-----BEGIN CERTIFICATE"));
        assert_eq!(tls.chain_pem.matches("BEGIN CERTIFICATE").count(), 2);
        assert!(tls.key_pem.contains("PRIVATE KEY"));
        assert!(tls.client_pem.starts_with("-----BEGIN CERTIFICATE"));
        assert!(tls.client_key_pem.contains("PRIVATE KEY"));
        assert!(tls.ca_key_pem.contains("PRIVATE KEY"));
    }
}
